INSERT INTO "convergence_assessment" ("convergence_id", "status", "clinical_sources", "co1_sources", "co2_sources", "down_weighted_sources", "discounted_sources", "rationale", "synthesis_approach", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (7, 'pending_assessment', '["REF-00983", "REF-00985", "REF-00986", "REF-00984"]', '["REF-00989", "REF-00993"]', '[]', '[]', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995", "REF-00997"]', 'PROXY: the regulatory stratum supplies the threshold (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)) and 6 anchoring-tier finding(s) supply the direction. The value is selected most-accommodatingly within what the threshold permits; no source states it. Owner 2026-09-16: ''yes it''s not perfect it''s a proxy''.', NULL, '2026-09-18 02:40:00', 'session_2026-09-18-research-batch-14-co2-professional-bodies', NULL, NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00998', NULL, NULL, 0, NULL, NULL, 0, NULL, 2025, NULL, 'FAQ: Environmental and Home Modifications', NULL, NULL, NULL, 'EN', 'page is English throughout', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://otaus.com.au/resources/faq-environmental-and-home-modifications', '2026-09-18', NULL, NULL, 5, 'national_fw', 'AU', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', 'retrieval_log.fetch', NULL, 1, NULL, 'FAQ › How should AS1428.1 be applied?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (87, 'AU', 'AS 1428.1:2021 — ramp gradients, landings and handrails', NULL, 'REFERENCE-ONLY', NULL, 'RAISED LATE, AND THE LATENESS IS THE POINT. Batch 13 admitted REF-00997, whose 1:14 and 1:8 recommendations are grounded in AS 1428.1, and filed no code lead at all -- R12 says code values go here, not into prose notes. Batch 14 adds it because the author asked whether the other concepts were being captured and the answer was no. WHAT IS STILL UNRETRIEVED: the clause and its value. Neither REF-00997 nor REF-00998 quotes a gradient FROM the standard -- REF-00997 states its own recommendation and REF-00998 says only that "the standard specifies requirements for ramp gradients, landings, and handrails". The standard is paywalled at Standards Australia (REF-00998 links the catalogue page), so this stays REFERENCE-ONLY under the 2026-08-12 ruling. SCOPE CAVEAT recorded with the lead: REF-00998 states AS 1428.1 does not apply to Class 1 and 2 buildings, so retrieving this clause gives a figure for public buildings, not homes.', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (88, 'AU', 'Livable Housing Design Standard (NCC, 2022)', NULL, 'REFERENCE-ONLY', NULL, 'The instrument that covers private dwellings, which AS 1428.1 does not. Named by Occupational Therapy Australia (REF-00998), which also records that the Livable Housing Guidelines are ADVISORY. Surfaced with a direct URL in the FAQ (ncc.abcb.gov.au/sites/default/files/resources/2023/livable-housing-design-20221219.pdf) and NOT retrieved by this batch -- staged honestly rather than described from a link. If it states a gradient for dwellings it is the first instrument in this corpus that governs the setting a home ramp is actually in.', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (58, 'accessible-circulation-geometry', 'INT', 'EN', 2, 'co2', 'international', 'World Federation of Occupational Therapists WFOT position statement built environment accessibility ramp gradient', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'ZERO, AND R14 SAYS WHICH KIND: QUERY-SHAPE FAILURE FIRST, THEN A THIN GENUINE ABSENCE. The open-web query returned building-industry and access-board pages and not one wfot.org result, which is a query-shape result, not evidence about WFOT. Went to the source instead (R10): wfot.org/resources and wfot.org/search?q=ramp both returned 403; the Wayback rung on the query-string URL 404d; the rung on https://www.wfot.org/resources returned 200 (103053 bytes, sha256 b4b2be12...). That index lists WFOT resource categories -- Position Statements, Guidelines, Publications, Standards -- and its indexed text contains ZERO occurrences of ramp, gradient, slope, accessib*, housing or built environment. THAT IS WEAK EVIDENCE AND IS LABELLED AS SUCH: the page is a JavaScript-rendered navigation shell with only ~3800 characters of extractable text, so its silence is a rendering fact as much as a content fact. What can be said honestly: no WFOT gradient was found by open web search or by the retrievable resource index, and WFOT remains the least-searched of the three bodies. NOT saturated.', 0, 'PRIORS.md (committed 6893397, before any query): a federation publishes position statements, not dimensions; a ramp gradient is a building-code fact and sits outside what an international federation asserts. Expect a well-formed zero.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (59, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co2', 'national', 'ramp gradient slope home modification accessibility', NULL, 'web', 'systematic', NULL, 10, 10, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'DOMAIN-SCOPED TO wfot.org, caot.ca AND otaus.com.au -- jurisdiction deliberately OMITTED because the query spanned three. This is the query that worked, and the per-body outcome is the finding. CAOT: "OT PRACTICE DOCUMENT: Home Assessment and Modifications", Spring 2024, retrieved (200, 203046 bytes, sha256 81fc675f...) and READ IN FULL -- 2 pages. The word "ramp" occurs ONCE, in a list of what an OT recommends ("bar grabs, handrails, ramps, raised toilet seats"). gradient, slope, 1:12 and 1:20 occur ZERO times. Its companion HomeModification_FactSheet.pdf (200, 122223 bytes) contains none of them either. A national OT professional body practice document on home modification names the ramp and states no dimension: that is RCOT Adaptations without Delay replicated in Canada, and it is a GENUINE ABSENCE, fully read, not a retrieval failure. OTA: FAQ Environmental and Home Modifications, admitted REF-00998 -- see that row. NOT admitting CAOT: it holds no extraction for parameter 3, and admitting a source to carry a zero is not what evidence_sources is for; batch 12 treated its four Co-1 zeroes the same way.', 0, 'PRIORS.md (committed 6893397, before any query): CAOT will defer to the National Building Code of Canada if it addresses gradient at all; Occupational Therapy Australia is the most likely of the three to state something, and for that same reason most likely to point at AS 1428.1 rather than carry its own number.');
INSERT INTO "economics_entries" ("entry_id", "pillar", "entry_type", "source", "ref_id", "jurisdiction", "finding", "study_design", "sample", "value_numeric", "value_unit", "currency", "bcr", "evidence_tier", "confidence", "source_section", "quant_status", "year", "journal", "status", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('ECON-001', 'construction', 'research_gap', 'Foundations (national body for home improvement agencies, England), "Guidance For Ramp Adaptations" — retrieved by session_2026-09-18-research-batch-13-co2-occupational-therapy via the R10 Wayback ladder, snapshot 2023-12-07, sha256 b201d3bea81d54e1e509e7d18d02ddc67227e5fa83c5e5e10f2741ddea6920d3', NULL, 'GB', 'There is little research investigating the cost comparison between rampscaping, traditional ramps and lifts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'OPEN', 'AN ABSENCE OF EVIDENCE, STATED BY A NATIONAL BODY, AND THEREFORE FIRST-CLASS (R7). Captured LATE: batch 13 read this sentence, used the page for a different purpose -- falsifying a gradient attribution -- and left the economics finding in prose, which R12 forbids. Filed here rather than backdated into batch 13, because the migration carrying that batch is committed and rule 3 is fix-forward. The page continues: "In general, the steeper the land around the home the more complex and expensive rampscaping would be. On flatter sites grading a tonne of topsoil is likely to cost much less than edging kerbs and handrails." That is a directional cost claim with no figure, which is why value_numeric is empty and the entry_type is research_gap rather than cost_premium. NOT ADMITTED AS A SOURCE: the Foundations page is resolved OUT-OF-SCOPE for parameter 3 (candidate 72), so this entry carries --source rather than a ref_id.', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-00998-MOB', 'REF-00998', 'MOB', 'No study population — a professional association FAQ explaining the scope of a standard; no participants, no measurement', NULL, 'PROXY', 'PROXY on the same ground as every regulatory-stratum row in this cell. Noted because the tier call here was the batch question: Occupational Therapy Australia IS the OT professional body, so Co-2 was live. Refused because Co-2 in governance/tier-system.md means professional-body CLINICAL PRACTICE GUIDELINES, and an FAQ page explaining an Australian Standard is not a CPG -- it carries no clinical warrant, no consensus process and no cited evidence. Admitting it Co-2 would have given this batch the Co-2 source it was convened to find, which is exactly why it was refused.', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', 'REF-00998', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (140, 'REF-00998', 1, NULL, NULL, NULL, NULL, 1, 'Occupational Therapy Australia', NULL, 'author', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', NULL);
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (27, 'REF-00998', 'Class 1 and 2 buildings', 'EN', 'How should AS1428.1 be applied?', 'it does not apply to Class 1 and 2 buildings, which are single dwellings (like houses) and those with multiple units (like apartments), respectively', 'THE CATEGORY THAT DECIDES WHETHER THE THRESHOLD APPLIES. A building-classification term doing load-bearing work on an accessibility question: whether a ramp gradient standard reaches the place a disabled person actually lives. Recorded verbatim and unjudged (D-0173).', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (28, 'REF-00998', 'Livable Housing Design Standard', 'EN', 'What are the Livable Housing Design requirements?', 'Livable Housing Guidelines are advisory', 'The advisory instrument that occupies the space AS 1428.1 vacates for private dwellings. Named by the professional body as the thing to consider when the mandatory standard does not apply. Unjudged (D-0173).', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (29, 'REF-00998', 'private dwellings', 'EN', 'What guidelines or standards should be considered when renovating or modifying private dwellings?', 'While AS1428.1 does not apply to private dwellings, and Livable Housing Guidelines are advisory', 'The setting this whole parameter is about for a home ramp, and the setting both instruments decline to bind. Unjudged (D-0173).', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (59, 'REF-00998', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (86, NULL, 'accessible-circulation-geometry', NULL, 'MISCELLANEOUS', 'CAOT, "OT PRACTICE DOCUMENT: Home Assessment and Modifications", Spring 2024 — the Canadian national OT professional body practice document. READ IN FULL (2 pages) and it states NO ramp gradient: "ramp" appears once, in a list of recommended modifications, and gradient/slope/1:12/1:20 appear zero times. Recorded so the next session does not re-retrieve it expecting a figure.', 'https://caot.ca/document/8205/Home%20Assessment%20and%20Modifications%20EN.pdf', 'RESOLVED', 2, 0, 'Holds no extraction for parameter 3. It is the closest document in this corpus to a Co-2 CPG -- a national professional body practice document -- and it is silent on the dimension, which is a finding about the evidence base rather than evidence about a gradient. Batch 12 treated its four Co-1 zeroes the same way: recorded, not admitted.', NULL, 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (87, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'WFOT (World Federation of Occupational Therapists) resource library — the international federation, and the LEAST searched of the three professional bodies this batch targeted. R15 HYPOTHESIS, UNTESTED: a federation publishes position statements on occupational justice and professional scope, not building dimensions, so a gradient is unlikely to exist. That is a prediction, not a result.', 'https://wfot.org/resources', 'UNVERIFIED', 2, 0, 'RETRIEVAL LIMITATION, NOT ABSENCE. wfot.org returns 403; the Wayback rung on the resources index returned 200 but the page is a JavaScript-rendered shell with ~3800 characters of extractable text, so its silence on ramp/gradient/accessibility is a rendering fact as much as a content fact. Untried rungs: the members area, WFOT position statements as individually-linked PDFs, and the WFOT Bulletin in a journal index.', NULL, 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00998', 'accessible-circulation-geometry', '17', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (36, 'REF-00998', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'AU', 'private dwellings (Class 1 and 2)', 'qualitative', 'AS 1428.1 does not apply to private dwellings; it governs Class 2-9 buildings', NULL, 'AS 1428.1:2021 provides the minimum design requirements for building work to enable access for people with disabilities in Class 2-9 buildings. As such, it does not apply to Class 1 and 2 buildings, which are single dwellings (like houses) and those with multiple units (like apartments), respectively.', 'How should AS1428.1 be applied?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THIS QUALIFIES THE THRESHOLD REF-00997 APPLIES, AND IT IS WHY THIS PAGE WAS ADMITTED AT ALL. REF-00997 (SA prescriber guidance) recommends 1:14 and 1:8 for ramps at private homes and grounds those figures in AS 1428.1. The Australian professional body states that AS 1428.1 DOES NOT APPLY to Class 1 and 2 buildings -- houses and apartments. So the figure governing home ramps in that document is borrowed from a standard that formally excludes homes. REF-00997 half-acknowledges this in its own words ("As ramps are generally on the outside of a building, even a ramp at a private home is likely to be accessed by members of the public at times"), which is a rationale for borrowing it, not a claim that it applies. Recorded as a finding, not a claim: it states no gradient and supplies no value. It reaches a determination only through the proxy branch (086), and REF-00998 is T5 so it is not an anchoring-tier finding either -- it changes no number. What it changes is what a reader should believe about the number.', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:35', 'session_2026-09-18-research-batch-14-co2-professional-bodies', 'finding', NULL);
INSERT INTO "specifications" ("specification_id", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "state", "design_scale", "convergence_id", "confidence_dimensions_present", "confidence_dimensions_absent", "confidence_synthesis_basis", "gap_register_id", "not_applicable_rationale", "tier_basis", "governing_refs", "rule_version", "derivation_sha", "code_floor_only", "value_min", "value_max", "value_unit", "falsification_condition", "has_unverified_sources", "all_sources_disqualified", "regulatory_stratum_only", "created_at", "created_by_session", "updated_at", "updated_by_session", "value_note", "functional_basis", "derivation_rationale", "cultural_claim_anchor", "derivation_paths", "retired_at", "retired_by_session", "retirement_reason", "superseded_by_specification_id", "rests_on_proxy_inference", "value_notations") VALUES (7, 3, 'MOB', NULL, NULL, NULL, 'provisional', 'universal', 7, '["Tier 4-5 standards (3)", "Tier 6 statutory codes (5)", "Anchoring-tier findings supplying direction (6: T1+CO1+T2)"]', '["No source states a value for this parameter at an anchoring tier -- the threshold is regulatory and the direction is inferred, so this is a PROXY determination and not a best-practice claim"]', 'Threshold from the regulatory stratum (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)), direction from measured findings. A proxy inference under the owner statement of 2026-09-16, marked as one.', NULL, NULL, 'T4-6-only-threshold+T1+CO1+T2-direction(proxy_inference)', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995", "REF-00997"]', 'pilot-3', 'e328e079200274fb779607516b9b13556e320032f85731c07901270004ebb40b', 0, NULL, 5.0, '%', 'Overturned if a source states a value for this parameter at an anchoring tier (the cell then rests on that, not on a proxy), if the findings supplying direction are retracted or re-graded off `finding`, or if the cited threshold editions are superseded. It does NOT become a best-practice claim by more codes agreeing (§2.7), and the proxy step is degenerate without the threshold: ''best outcomes'' alone resolves to the gentlest gradient physically possible, which for a ramp is not a ramp.', 0, 0, 0, '2026-09-18 02:40:00', 'session_2026-09-18-research-batch-14-co2-professional-bodies', '2026-09-18 02:40:00', 'session_2026-09-18-research-batch-14-co2-professional-bodies', 'value presented in 2 notations of one quantity (owner ruling 2026-09-17: present both, never choose)', '[{"icf_code": "d410", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d420", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d450", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d455", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d460", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d465", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d470", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d510", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "ma